import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CdvW4CUT.js";const d=JSON.parse('{"title":"伺服人員招募文件(第一期)","description":"","frontmatter":{},"headers":[],"relativePath":"web/recruit/1/index.md","filePath":"web/recruit/1.md"}'),e={name:"web/recruit/1/index.md"};function r(t,l,u,o,h,p){return i(),n("div",null,[...l[0]||(l[0]=[s(`<h1 id="伺服人員招募文件-第一期" tabindex="-1">伺服人員招募文件(第一期) <a class="header-anchor" href="#伺服人員招募文件-第一期" aria-label="Permalink to &quot;伺服人員招募文件(第一期)&quot;">​</a></h1><h2 id="文件說明" tabindex="-1">文件說明 <a class="header-anchor" href="#文件說明" aria-label="Permalink to &quot;文件說明&quot;">​</a></h2><p>這是一份招募、規範、伺服人員的行為與說明文件，適用對象為全伺服人員(包含服主) 同時此文件也公開給玩家，讓玩家知道伺服人員應該遵守什麼事情</p><p>如果你是個玩家，你可以簡單閱讀一下，如果哪天伺服人員使用了職權，但不符合文件的規範，這是伺服人員的失職，請告訴服主，我會處理，確保玩家(你)權益不受損</p><p>如果你想成為伺服人員，你務必要完整閱讀，確保你對伺服人員的&quot;概念&quot;是建立起來的，並且你要有為這份工作負責的概念</p><p>當伺服人員真的不難，我們要的是人格特質適合的人，而不是要什麼能力超猛的人，如果你看的懂，我們非常歡迎你加入伺服人員</p><h2 id="概念建立" tabindex="-1">概念建立 <a class="header-anchor" href="#概念建立" aria-label="Permalink to &quot;概念建立&quot;">​</a></h2><ul><li>伺服人員，代表著<strong>伺服器</strong>，而不是代表著&quot;你&quot;</li><li>伺服器需為全體玩家著想，而伺服人員需為伺服器朝想，<br> 意味著你(伺服人員)必須為全體玩家著想</li><li>在所有決策與行為(尤其是使用職權時)上，請隨時假設:<br> 所有玩家都看的到你在用什麼職權，<br> 並且去評估<code>玩家會對你這樣做 有什麼想法</code></li><li>當你不行使權限時，你想怎麼做就怎麼做(當一個無壓力的玩家)<br> 當你使用任何權限時，你代表著是伺服器</li><li>再說一次，當你在<strong>使用職權</strong>時，請切記 : 你，代表著伺服器</li></ul><h2 id="伺服人員條件與要求" tabindex="-1">伺服人員條件與要求 <a class="header-anchor" href="#伺服人員條件與要求" aria-label="Permalink to &quot;伺服人員條件與要求&quot;">​</a></h2><h3 id="我們不要求以下幾點" tabindex="-1">我們不要求以下幾點 <a class="header-anchor" href="#我們不要求以下幾點" aria-label="Permalink to &quot;我們不要求以下幾點&quot;">​</a></h3><ul><li>你不需要事先學會任何技術 <ul><li>你什麼都不會也沒關係，我們會教你，同時，你不想要也可以不學</li></ul></li><li>你不需要有什麼工作業績 <ul><li>伺服人員沒什麼工作要做，你都沒做事，<strong>也不會怎樣</strong><br> 更準確來說是，伺服人員根本沒什麼事情能做的</li></ul></li><li>你不需要天天上線工作 <ul><li>我們根本沒什麼工作要讓你做</li></ul></li></ul><h3 id="伺服人員依然還是玩家-身分轉換要求" tabindex="-1">伺服人員依然還是玩家 身分轉換要求 <a class="header-anchor" href="#伺服人員依然還是玩家-身分轉換要求" aria-label="Permalink to &quot;伺服人員依然還是玩家 身分轉換要求&quot;">​</a></h3><ul><li>平時沒工作時，你就繼續當個玩家玩就好，我不會管你平時要幹嘛 <ul><li>切記，當平時無公務時(平時99%時間真的沒公務)，絕對不可使用<strong>任何</strong>伺服人員權限</li></ul></li><li>當任何事情發生時，而你是最早知道的伺服人員 <ul><li>若此行為以&quot;伺服人員&quot;角度來看，相當的不該發生，你應該立即阻止，並避免事件擴大</li><li>再次強調，伺服人員要避免做出，讓&quot;大多數玩家&quot;認為不妥的行為，縱使那件事沒有錯</li><li>請注意，你是有伺服人員的身分的</li><li>就算那件事是同社區的玩家，甚至是你的好朋友也一樣</li></ul></li></ul><h3 id="我們希望你具備以下幾點-希望-非必要" tabindex="-1">我們希望你具備以下幾點(希望 非必要) <a class="header-anchor" href="#我們希望你具備以下幾點-希望-非必要" aria-label="Permalink to &quot;我們希望你具備以下幾點(希望 非必要)&quot;">​</a></h3><ul><li>了解身分所代表的涵義 <ul><li>這件事對某些人來說是再簡單不過的條件，但對某些人來說相當困難或不好理解<br> 總之，若你明白身分的含意與知道如何應對，你會非常適合當伺服人員的<br> 但若不明白的話，我們希望你還是當個玩家就好</li></ul></li><li>心智年齡自認國中畢業以上 <ul><li>年齡不是必要條件，不過我們還是希望你成熟點</li></ul></li><li>別當個幽靈 <ul><li>伺服人員的組織也是個社區，有著伺服人員頻道，裡面也不只聊著跟伺服有關的事情(大部分都不太重要)，可以的話還是多參與跟出沒</li></ul></li><li>了解保密的重要性 <ul><li>有時候我們有些伺服人員的訊息並不希望讓玩家知道(例如:我們在嘗試抓外掛或怪異玩家、內部測試用資訊或數據)，我們不希望你向任何人說</li></ul></li><li>有Google帳號 <ul><li>用於編輯內部文件用</li></ul></li></ul><h2 id="伺服人員-有什麼職位" tabindex="-1">伺服人員 有什麼職位? <a class="header-anchor" href="#伺服人員-有什麼職位" aria-label="Permalink to &quot;伺服人員 有什麼職位?&quot;">​</a></h2><h3 id="_1-遊戲管理員" tabindex="-1">1. 遊戲管理員 <a class="header-anchor" href="#_1-遊戲管理員" aria-label="Permalink to &quot;1. 遊戲管理員&quot;">​</a></h3><ul><li>負責遊戲事務處理</li><li>工作與權限，看下面說明</li></ul><h3 id="_2-商店街負責人" tabindex="-1">2. 商店街負責人 <a class="header-anchor" href="#_2-商店街負責人" aria-label="Permalink to &quot;2. 商店街負責人&quot;">​</a></h3><ul><li>工作有點繁雜也比較多，但不難的</li><li>要負責商店街營運的事情+畫作同步+美術館擺放畫作</li><li>有定期的遊戲幣薪水</li><li>工作與權限，看下面說明</li></ul><h3 id="_3-其他業務" tabindex="-1">3. 其他業務 <a class="header-anchor" href="#_3-其他業務" aria-label="Permalink to &quot;3. 其他業務&quot;">​</a></h3><ul><li><strong>沒有任何遊戲內權限</strong></li><li>企劃/建築/開發/文件維護/網站維護/... <ul><li>企劃 : 任何活動企劃/插件或功能想法企劃/副本企劃，總之就是提點子的</li><li>開發 : (插件)伺服器Java插件開發</li><li>文件維護/網站維護 : 內部資料維護與設計文件/Hackmd網站維護/gitbook網站維護/撰寫文件</li></ul></li><li>如果你想當上述的職位，你可以提出來，我們會跟你討論</li></ul><h3 id="_4-高層人員" tabindex="-1">4. 高層人員 <a class="header-anchor" href="#_4-高層人員" aria-label="Permalink to &quot;4. 高層人員&quot;">​</a></h3><ul><li>不開放徵選，由服主與高層人員共同決定人選</li><li>擁有遊戲管理員+商店街負責人的權限</li><li>參與伺服人員編制與調動的討論</li><li>一樣還是玩家</li></ul><h3 id="共同職位-所有職位都有的權力與責任-這不是一個職位" tabindex="-1">共同職位(所有職位都有的權力與責任) 這不是一個職位 <a class="header-anchor" href="#共同職位-所有職位都有的權力與責任-這不是一個職位" aria-label="Permalink to &quot;共同職位(所有職位都有的權力與責任) 這不是一個職位&quot;">​</a></h3><ul><li>可以看到管理員頻道</li><li>都有Discord權限，可以踢人</li><li>日常業務:加Discord新人，<strong>主動</strong>參與內部討論</li><li>你可以兼任多職位，如果你想要的話</li><li>共同職位不是一個職位，是每個伺服人員都該做的</li></ul><h2 id="遊戲管理員" tabindex="-1">遊戲管理員 <a class="header-anchor" href="#遊戲管理員" aria-label="Permalink to &quot;遊戲管理員&quot;">​</a></h2><h3 id="工作" tabindex="-1">工作 <a class="header-anchor" href="#工作" aria-label="Permalink to &quot;工作&quot;">​</a></h3><ul><li>如果有人正在破壞，玩家說:<code>幹我家正在被拆誰來救我</code>，你可以處理 <ul><li>流程:你可以過去看，確認好之後馬上對當事人進行封鎖(ban 1天)</li><li>管理員沒有裁決案件時間的權力(外掛或極大規模破壞除外) <ul><li>管理員比起當警察，更像是開救護車的，當事情發生時，你能馬上封鎖他1天，讓此事件止血(畢竟玩家阻止不了他家被拆)</li><li>ban完一天之後，剩下就沒你的事情了，這個工作大約只需要一分鐘</li></ul></li></ul></li><li>如果有人被檢舉，檢舉看起來的確是屬實，而被檢舉的當事人還在線上，你可以處理 <ul><li>一樣，ban一天，剩下沒你的事情了</li></ul></li><li>如果有人發現開外掛，你確認是的話，你可以馬上永ban該玩家</li><li>處理告示牌更改ID</li><li>加Discord新人</li><li>回覆客服的事情與幫忙處理</li><li>上述這些工作一天加起來大概不到20分鐘的工作時間</li><li>剩下非必要的工作，想做就做，不想做也沒差，做了可以當個好人，幫別人撿起皮夾 <ul><li>看到被破壞你可以幫忙檢舉</li><li>看到玩家有問題你主動告訴他答案，而不是只有/rule,/suicide,網站上都有你都不看 的回答</li></ul></li></ul><h3 id="權限" tabindex="-1">權限 <a class="header-anchor" href="#權限" aria-label="Permalink to &quot;權限&quot;">​</a></h3><ul><li>可以強制拆鎖住的告示牌 <ul><li>不能直接開 你只能拆掉後再開 <ul><li>在幫玩家處理拆告示牌的客服時會用到</li><li>其餘時候你用不到，你強制拆了玩家牌子，但對方未同意，會是你違規</li></ul></li></ul></li><li>查詢玩家IP或分身等資訊 <ul><li>不准把玩家IP洩漏出去，這是玩家個人資料</li></ul></li><li>強制傳送到別的玩家身旁/強制把對方拉過來 <ul><li><strong>平時不准亂用，僅限於案件處理時的需要你才能用這指令</strong></li></ul></li><li>指令獲得隱形效果(無氣泡)</li><li>直接以指令跳轉伺服 <ul><li>我知道這很方便，但非公務狀況不准用</li><li>例如:有玩家表示主二有人在大拆特拆我家，而你在主一，你可以用指令馬上去主二，之後強制傳送至該玩家身邊確認狀況</li></ul></li><li>切換為觀察者模式 <ul><li>無法利用觀察者來移動(切回生存時會回原地)</li></ul></li></ul><h2 id="商店街負責人" tabindex="-1">商店街負責人 <a class="header-anchor" href="#商店街負責人" aria-label="Permalink to &quot;商店街負責人&quot;">​</a></h2><h3 id="工作-1" tabindex="-1">工作 <a class="header-anchor" href="#工作-1" aria-label="Permalink to &quot;工作&quot;">​</a></h3><ul><li>負責商店街的各種事務 <ul><li>租店/收租金/催繳租金/幫忙設置商人/設置領地權限</li><li>我們會慢慢教你怎麼做和指令，但也希望你學習能力不要太差</li></ul></li><li>畫作同步與美術館維護 <ul><li>負責畫作的同步設定</li><li>也要把畫作擺放到美術館內部(如果玩家要展示的話)</li></ul></li><li>薪水 <ul><li>有薪水(待定)</li><li>玩家手殘刪掉商人的話，500工本費是屬於你的</li></ul></li></ul><h3 id="權限-1" tabindex="-1">權限 <a class="header-anchor" href="#權限-1" aria-label="Permalink to &quot;權限&quot;">​</a></h3><ul><li>領地設置與使用</li><li>圖畫同步</li></ul><h2 id="加入方式" tabindex="-1">加入方式 <a class="header-anchor" href="#加入方式" aria-label="Permalink to &quot;加入方式&quot;">​</a></h2><ul><li>首先，請將下面大格子的問題複製起來，回答完成後，加入招募群組(寫在公告上) <ul><li><strong>最好能多寫點你的想法</strong></li></ul></li><li>接著，我們會與你在私人頻道討論，了解雙方的想法 <ul><li>請盡量不要讓我們等你的答案等太久</li><li>私人頻道內的討論與你的回答，我們都不會公開(但會有紀錄)， 全程只有現任管理員知道，請放心</li></ul></li><li>最後會進行公告結果</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Minecraft ID : </span></span>
<span class="line"><span>Discord ID(包含#) : </span></span>
<span class="line"><span>你的年齡(請不要謊報) : </span></span>
<span class="line"><span>平時是否可使用語音? :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>玩Minecraft多久了? </span></span>
<span class="line"><span>玩這個服多久了? </span></span>
<span class="line"><span>有玩過其他伺服嗎?</span></span>
<span class="line"><span>如果有，玩多久呢?能簡單描述一下那個服在玩什麼嗎?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你對這伺服，以你遊玩的感覺來說，有什麼心得或想法?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你想做哪個職位?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果你是管理員，你也跟朋友或熟人一起玩伺服，今天你朋友或熟人違規了，你的想法或做法是什麼?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>對於公開文件所說的&quot;概念建立&quot;與其他要點，你的看法或理解是什麼?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>有什麼想了解的問題/想說的/你自己的看法，請補充在下方</span></span></code></pre></div>`,39)])])}const b=a(e,[["render",r]]);export{d as __pageData,b as default};
